import{_ as s,o as t,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-10-26（物理 / 阿秒光脉冲 / 行星高压冰）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-26-physics.md","filePath":"topics/physics/science-daily-2026-10-26-physics.md"}'),e={name:"topics/physics/science-daily-2026-10-26-physics.md"};function i(c,o,g,l,a,d){return t(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-26-物理-阿秒光脉冲-行星高压冰" tabindex="-1">科学日报 · 2026-10-26（物理 / 阿秒光脉冲 / 行星高压冰） <a class="header-anchor" href="#科学日报-·-2026-10-26-物理-阿秒光脉冲-行星高压冰" aria-label="Permalink to &quot;科学日报 · 2026-10-26（物理 / 阿秒光脉冲 / 行星高压冰）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> — 第45期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-physics</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-26-100-mj-级亚周期中红外激光——逼近「单两位数阿秒」脉冲" tabindex="-1">科学日报 2026-10-26：100 mJ 级亚周期中红外激光——逼近「单两位数阿秒」脉冲 <a class="header-anchor" href="#科学日报-2026-10-26-100-mj-级亚周期中红外激光——逼近「单两位数阿秒」脉冲" aria-label="Permalink to &quot;科学日报 2026-10-26：100 mJ 级亚周期中红外激光——逼近「单两位数阿秒」脉冲&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ DOI: 10.1126/sciadv.aed5357 ｜ Science Advances (2026)</p></blockquote><ul><li>原理约束：高次谐波产生（HHG）的<strong>孤立阿秒脉冲时长，由驱动激光的光学周期数决定</strong> → 要<strong>更短</strong>的软 X 射线阿秒脉冲，就必须<strong>在保持高脉冲能量的同时把周期数压到最少</strong>。这是「<strong>能量</strong>」与「<strong>周期数</strong>」的一对硬权衡。</li><li>本工作：一套<strong>载波包络相位（CEP）稳定</strong>的 <strong>100 mJ 级亚周期中红外激光</strong>：中心波长 <strong>2.26 μm</strong>，输出 <strong>50 mJ、6.7 fs（0.88 个光学周期）</strong> 的脉冲 —— <strong>能量比以往任何亚周期激光高出两个数量级</strong>。</li><li>验证：用它做 HHG，并与<strong>三维含时薛定谔方程（3D-TDSE）模拟</strong>对比，识别出亚周期激光的<strong>独特特征</strong>。</li><li>意义：迈向<strong>高能半周期激光</strong>与<strong>高能单两位数阿秒软 X 射线脉冲</strong>的决定性一步，用于探测<strong>此前无法企及时间尺度</strong>的物质与光—物质相互作用。</li><li>洞察（对本库 <code>physics</code>）： <ol><li>「<strong>把三个互相拉扯的参数同时推到位</strong>」——<strong>能量、周期数、CEP 稳定性</strong>任何一项单独优化都不难，难的是<strong>同时</strong>。这与本库 10-24「用交替+脉冲热输入让增材制造的准稳态与循环波动不再互斥」（<code>topics/materials/science-daily-2026-10-24-materials.md</code>）是<strong>同一种手法</strong>：<strong>当两个目标被一条通道绑成权衡时，先拆开它们各自的时间尺度/自由度</strong>。</li><li>方法上，<strong>模拟（3D-TDSE）不是事后拟合，而是用来「识别独特特征」</strong> —— 即<strong>用理论当鉴别器</strong>，把真正的新效应从仪器效应里分离出来。可迁移判据：<strong>当实验进入一个此前无人到过的参数区，理论模拟的第一作用不是预测数值，而是给出「哪些量应该呈现什么特征」的鉴别标准。</strong></li></ol></li></ul><hr><h2 id="科学日报-2026-10-26-大型海洋世界的「高压冰」其实能容纳氨基酸" tabindex="-1">科学日报 2026-10-26：大型海洋世界的「高压冰」其实能容纳氨基酸 <a class="header-anchor" href="#科学日报-2026-10-26-大型海洋世界的「高压冰」其实能容纳氨基酸" aria-label="Permalink to &quot;科学日报 2026-10-26：大型海洋世界的「高压冰」其实能容纳氨基酸&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-26.md</code> ｜ DOI: 10.1126/sciadv.aec2045 ｜ Science Advances (2026)</p></blockquote><ul><li>问题：在<strong>大型冰卫星与系外行星（ocean worlds）<strong>上，水海洋被</strong>厚厚的高压冰层（冰 VI / 冰 VII）<strong>与</strong>岩石内部</strong>隔开，<strong>阻碍</strong>了水—岩相互作用产生的<strong>营养物与有机物</strong>直接释放到海洋中。这些<strong>生命必需化合物能否被高压冰吸收</strong>（决定其在海洋中的可用性），此前<strong>约束很差</strong>。</li><li>方法（直接测，不靠外推）：用<strong>金刚石压腔（diamond-anvil cell）<strong>在</strong>高温高压</strong>条件下测定<strong>甘氨酸与丙氨酸进入冰 VI、冰 VII 的分配系数</strong>： <ul><li>Kp(甘氨酸) = <strong>0.14（冰 VI）</strong>、<strong>0.40（冰 VII）</strong>；</li><li>Kp(丙氨酸) = <strong>0.21（冰 VI）</strong>、<strong>0.35（冰 VII）</strong>。</li></ul></li><li>机制：<strong>第一性原理计算</strong>表明氨基酸可通过**「共生长」（cogrowth）**方式嵌入高压冰的晶格。</li><li>结论：氨基酸与高压冰的<strong>中等相容性</strong>，<strong>有利于它们在外星海洋中输运</strong> → <strong>为宜居性打开一条通道</strong>（高压冰层不是绝对的「死隔板」）。</li><li>洞察（对本库 <code>physics</code> × <code>space-energy</code> × <code>ai-brain</code>）： <ol><li><strong>「隔板」的默认假设被拆掉</strong> —— 高压冰长期被当成海洋世界宜居性的<strong>否决项</strong>（「营养物下不去」）。本条把问题从**「有没有隔板」<strong>换成</strong>「隔板的渗透率是多少」<strong>，于是</strong>定性否决变成定量参数**。可迁移判据：<strong>当一个条件被当作「不可能」的硬约束时，先把它改写成「一个带数值的通过率」。</strong></li><li>这与本库 10-19「Bulqizë 断层天然氢储库的流固—地质力学耦合建模证明其可作『预验证』地下储氢场址」是同一族：<strong>把「能不能」的问题，改成「漏失率多大 / 容量多大」的可计算问题</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ 第45期 科学板块</p></blockquote><p>关键词：孤立阿秒脉冲、高次谐波产生 HHG、亚周期激光、载波包络相位 CEP、2.26 μm、6.7 fs、0.88 周期、100 mJ 级、三维含时薛定谔方程 3D-TDSE、能量与周期数的硬权衡、光谱学、海洋世界 ocean worlds、高压冰 冰 VI 冰 VII、金刚石压腔、分配系数、甘氨酸丙氨酸、共生长 cogrowth、宜居性、把不可能改写成通过率</p><p>关联：<code>topics/physics/science-daily-2026-10-24-physics.md</code>（声子热霍尔）、<code>topics/physics/science-daily-2026-10-23-physics.md</code>（电流驱动分子机器）、<code>topics/physics/spectroscopy.md</code>、<code>topics/physics/space-exploration-deep.md</code>、<code>topics/physics/index.md</code></p>',14)])])}const m=s(e,[["render",i]]);export{h as __pageData,m as default};
